176	//===----------------------------------------------------------------------===//
177	// ToyToLLVMLoweringPass
178	//===----------------------------------------------------------------------===//
179	
180	namespace {
181	struct ToyToLLVMLoweringPass
182	    : public PassWrapper<ToyToLLVMLoweringPass, OperationPass<ModuleOp>> {
183	  MLIR_DEFINE_EXPLICIT_INTERNAL_INLINE_TYPE_ID(ToyToLLVMLoweringPass)
184	  StringRef getArgument() const override { return "toy-to-llvm"; }
185	
186	  void getDependentDialects(DialectRegistry &registry) const override {
187	    registry.insert<LLVM::LLVMDialect, scf::SCFDialect>();
188	  }
189	  void runOnOperation() final;
190	};
191	} // namespace
192	
193	void ToyToLLVMLoweringPass::runOnOperation() {
194	  // The first thing to define is the conversion target. This will define the
195	  // final target for this lowering. For this lowering, we are only targeting
196	  // the LLVM dialect.
197	  LLVMConversionTarget target(getContext());
198	  target.addLegalOp<ModuleOp>();
199	
200	  // During this lowering, we will also be lowering the MemRef types, that are
201	  // currently being operated on, to a representation in LLVM. To perform this
202	  // conversion we use a TypeConverter as part of the lowering. This converter
203	  // details how one type maps to another. This is necessary now that we will be
204	  // doing more complicated lowerings, involving loop region arguments.
205	  LLVMTypeConverter typeConverter(&getContext());
206	
207	  // Now that the conversion target has been defined, we need to provide the
208	  // patterns used for lowering. At this point of the compilation process, we
209	  // have a combination of `toy`, `affine`, and `std` operations. Luckily, there
210	  // are already exists a set of patterns to transform `affine` and `std`
211	  // dialects. These patterns lowering in multiple stages, relying on transitive
212	  // lowerings. Transitive lowering, or A->B->C lowering, is when multiple
213	  // patterns must be applied to fully transform an illegal operation into a
214	  // set of legal ones.
215	  RewritePatternSet patterns(&getContext());
216	  populateAffineToStdConversionPatterns(patterns);
217	  populateSCFToControlFlowConversionPatterns(patterns);
218	  mlir::arith::populateArithToLLVMConversionPatterns(typeConverter, patterns);
219	  populateFinalizeMemRefToLLVMConversionPatterns(typeConverter, patterns);
220	  cf::populateControlFlowToLLVMConversionPatterns(typeConverter, patterns);
221	  populateFuncToLLVMConversionPatterns(typeConverter, patterns);
222	
223	  // The only remaining operation to lower from the `toy` dialect, is the
224	  // PrintOp.
225	  patterns.add<PrintOpLowering>(&getContext());
226	
227	  // We want to completely lower to LLVM, so we use a `FullConversion`. This
228	  // ensures that only legal operations will remain after the conversion.
229	  auto module = getOperation();
230	  if (failed(applyFullConversion(module, target, std::move(patterns))))
231	    signalPassFailure();
232	}
233	
234	/// Create a pass for lowering operations the remaining `Toy` operations, as
235	/// well as `Affine` and `Std`, to the LLVM dialect for codegen.
236	std::unique_ptr<mlir::Pass> mlir::toy::createLowerToLLVMPass() {
237	  return std::make_unique<ToyToLLVMLoweringPass>();
238	}
