72	namespace {
73	enum Action {
74	  None,
75	  DumpAST,
76	  DumpMLIR,
77	  DumpMLIRAffine,
78	  DumpMLIRLLVM,
79	  DumpLLVMIR,
80	  RunJIT
81	};
82	} // namespace
83	static cl::opt<enum Action> emitAction(
84	    "emit", cl::desc("Select the kind of output desired"),
85	    cl::values(clEnumValN(DumpAST, "ast", "output the AST dump")),
86	    cl::values(clEnumValN(DumpMLIR, "mlir", "output the MLIR dump")),
87	    cl::values(clEnumValN(DumpMLIRAffine, "mlir-affine",
88	                          "output the MLIR dump after affine lowering")),
89	    cl::values(clEnumValN(DumpMLIRLLVM, "mlir-llvm",
