1	//====- LowerToAffineLoops.cpp - Partial lowering from Toy to Affine+Std --===//
2	//
3	// Part of the LLVM Project, under the Apache License v2.0 with LLVM Exceptions.
4	// See https://llvm.org/LICENSE.txt for license information.
5	// SPDX-License-Identifier: Apache-2.0 WITH LLVM-exception
6	//
7	//===----------------------------------------------------------------------===//
8	//
9	// This file implements a partial lowering of Toy operations to a combination of
10	// affine loops, memref operations and standard operations. This lowering
11	// expects that all calls have been inlined, and all shapes have been resolved.
12	//
13	//===----------------------------------------------------------------------===//
14	
15	#include "mlir/IR/BuiltinAttributes.h"
16	#include "mlir/IR/BuiltinDialect.h"
17	#include "mlir/IR/BuiltinOps.h"
18	#include "mlir/IR/BuiltinTypes.h"
19	#include "mlir/IR/Diagnostics.h"
20	#include "mlir/IR/DialectRegistry.h"
21	#include "mlir/IR/PatternMatch.h"
22	#include "mlir/IR/ValueRange.h"
23	#include "mlir/Support/LLVM.h"
24	#include "mlir/Support/TypeID.h"
25	#include "toy/Dialect.h"
26	#include "toy/Passes.h"
27	
28	#include "mlir/Dialect/Affine/IR/AffineOps.h"
29	#include "mlir/Dialect/Arith/IR/Arith.h"
30	#include "mlir/Dialect/Func/IR/FuncOps.h"
31	#include "mlir/Dialect/MemRef/IR/MemRef.h"
32	#include "mlir/Pass/Pass.h"
33	#include "mlir/Transforms/DialectConversion.h"
34	#include "llvm/ADT/ArrayRef.h"
35	#include "llvm/ADT/STLExtras.h"
36	#include "llvm/ADT/Sequence.h"
37	#include "llvm/Support/Casting.h"
38	#include <algorithm>
39	#include <cstdint>
40	#include <functional>
41	#include <memory>
42	#include <utility>
43	
44	using namespace mlir;
45	
46	//===----------------------------------------------------------------------===//
47	// ToyToAffine Conversion Patterns
48	//===----------------------------------------------------------------------===//
49	
50	/// Convert the given RankedTensorType into the corresponding MemRefType.
51	static MemRefType convertTensorToMemRef(RankedTensorType type) {
52	  return MemRefType::get(type.getShape(), type.getElementType());
53	}
54	
55	/// Insert an allocation and deallocation for the given MemRefType.
56	static Value insertAllocAndDealloc(MemRefType type, Location loc,
57	                                   PatternRewriter &rewriter) {
58	  auto alloc = memref::AllocOp::create(rewriter, loc, type);
59	
60	  // Make sure to allocate at the beginning of the block.
61	  auto *parentBlock = alloc->getBlock();
62	  alloc->moveBefore(&parentBlock->front());
63	
64	  // Make sure to deallocate this alloc at the end of the block. This is fine
65	  // as toy functions have no control flow.
66	  auto dealloc = memref::DeallocOp::create(rewriter, loc, alloc);
67	  dealloc->moveBefore(&parentBlock->back());
68	  return alloc;
69	}
70	
71	/// This defines the function type used to process an iteration of a lowered
72	/// loop. It takes as input an OpBuilder and the range of loop induction
73	/// variables for the iteration. It returns a value to store at the current
74	/// index of the iteration.
75	using LoopIterationFn =
76	    function_ref<Value(OpBuilder &rewriter, ValueRange loopIvs)>;
77	
78	static void lowerOpToLoops(Operation *op, PatternRewriter &rewriter,
79	                           LoopIterationFn processIteration) {
80	  auto tensorType = llvm::cast<RankedTensorType>((*op->result_type_begin()));
81	  auto loc = op->getLoc();
82	
83	  // Insert an allocation and deallocation for the result of this operation.
84	  auto memRefType = convertTensorToMemRef(tensorType);
85	  auto alloc = insertAllocAndDealloc(memRefType, loc, rewriter);
86	
87	  // Create a nest of affine loops, with one loop per dimension of the shape.
88	  // The buildAffineLoopNest function takes a callback that is used to construct
89	  // the body of the innermost loop given a builder, a location and a range of
90	  // loop induction variables.
91	  SmallVector<int64_t, 4> lowerBounds(tensorType.getRank(), /*Value=*/0);
92	  SmallVector<int64_t, 4> steps(tensorType.getRank(), /*Value=*/1);
93	  affine::buildAffineLoopNest(
94	      rewriter, loc, lowerBounds, tensorType.getShape(), steps,
95	      [&](OpBuilder &nestedBuilder, Location loc, ValueRange ivs) {
96	        // Call the processing function with the rewriter and the loop
97	        // induction variables. This function will return the value to store at
98	        // the current index.
99	        Value valueToStore = processIteration(nestedBuilder, ivs);
100	        affine::AffineStoreOp::create(nestedBuilder, loc, valueToStore, alloc,
101	                                      ivs);
102	      });
103	
104	  // Replace this operation with the generated alloc.
105	  rewriter.replaceOp(op, alloc);
106	}
107	
108	namespace {
109	//===----------------------------------------------------------------------===//
110	// ToyToAffine Conversion Patterns: Binary operations
111	//===----------------------------------------------------------------------===//
112	
113	template <typename BinaryOp, typename LoweredBinaryOp>
114	struct BinaryOpLowering : public OpConversionPattern<BinaryOp> {
115	  using OpConversionPattern<BinaryOp>::OpConversionPattern;
116	  using OpAdaptor = typename OpConversionPattern<BinaryOp>::OpAdaptor;
117	
118	  LogicalResult
119	  matchAndRewrite(BinaryOp op, OpAdaptor adaptor,
120	                  ConversionPatternRewriter &rewriter) const final {
121	    auto loc = op->getLoc();
122	    lowerOpToLoops(op, rewriter, [&](OpBuilder &builder, ValueRange loopIvs) {
123	      // Generate loads for the element of 'lhs' and 'rhs' at the
124	      // inner loop.
125	      auto loadedLhs =
126	          affine::AffineLoadOp::create(builder, loc, adaptor.getLhs(), loopIvs);
127	      auto loadedRhs =
128	          affine::AffineLoadOp::create(builder, loc, adaptor.getRhs(), loopIvs);
129	
130	      // Create the binary operation performed on the loaded
131	      // values.
132	      return LoweredBinaryOp::create(builder, loc, loadedLhs, loadedRhs);
133	    });
134	    return success();
135	  }
136	};
137	using AddOpLowering = BinaryOpLowering<toy::AddOp, arith::AddFOp>;
138	using MulOpLowering = BinaryOpLowering<toy::MulOp, arith::MulFOp>;
139	
140	//===----------------------------------------------------------------------===//
141	// ToyToAffine Conversion Patterns: Constant operations
142	//===----------------------------------------------------------------------===//
143	
144	struct ConstantOpLowering : public OpConversionPattern<toy::ConstantOp> {
145	  using OpConversionPattern<toy::ConstantOp>::OpConversionPattern;
146	
147	  LogicalResult
148	  matchAndRewrite(toy::ConstantOp op, OpAdaptor adaptor,
149	                  ConversionPatternRewriter &rewriter) const final {
150	    DenseElementsAttr constantValue = op.getValue();
151	    Location loc = op.getLoc();
152	
153	    // When lowering the constant operation, we allocate and assign the constant
154	    // values to a corresponding memref allocation.
155	    auto tensorType = llvm::cast<RankedTensorType>(op.getType());
156	    auto memRefType = convertTensorToMemRef(tensorType);
157	    auto alloc = insertAllocAndDealloc(memRefType, loc, rewriter);
158	
159	    // We will be generating constant indices up-to the largest dimension.
160	    // Create these constants up-front to avoid large amounts of redundant
161	    // operations.
162	    auto valueShape = memRefType.getShape();
163	    SmallVector<Value, 8> constantIndices;
164	
165	    if (!valueShape.empty()) {
166	      for (auto i : llvm::seq<int64_t>(0, *llvm::max_element(valueShape)))
167	        constantIndices.push_back(
168	            arith::ConstantIndexOp::create(rewriter, loc, i));
169	    } else {
170	      // This is the case of a tensor of rank 0.
171	      constantIndices.push_back(
172	          arith::ConstantIndexOp::create(rewriter, loc, 0));
173	    }
174	
175	    // The constant operation represents a multi-dimensional constant, so we
176	    // will need to generate a store for each of the elements. The following
177	    // functor recursively walks the dimensions of the constant shape,
178	    // generating a store when the recursion hits the base case.
179	    SmallVector<Value, 2> indices;
180	    auto valueIt = constantValue.value_begin<FloatAttr>();
181	    std::function<void(uint64_t)> storeElements = [&](uint64_t dimension) {
182	      // The last dimension is the base case of the recursion, at this point
183	      // we store the element at the given index.
184	      if (dimension == valueShape.size()) {
185	        affine::AffineStoreOp::create(
186	            rewriter, loc, arith::ConstantOp::create(rewriter, loc, *valueIt++),
187	            alloc, llvm::ArrayRef(indices));
188	        return;
189	      }
190	
191	      // Otherwise, iterate over the current dimension and add the indices to
192	      // the list.
193	      for (uint64_t i = 0, e = valueShape[dimension]; i != e; ++i) {
194	        indices.push_back(constantIndices[i]);
195	        storeElements(dimension + 1);
196	        indices.pop_back();
197	      }
198	    };
199	
200	    // Start the element storing recursion from the first dimension.
201	    storeElements(/*dimension=*/0);
202	
203	    // Replace this operation with the generated alloc.
204	    rewriter.replaceOp(op, alloc);
205	    return success();
206	  }
207	};
208	
209	//===----------------------------------------------------------------------===//
210	// ToyToAffine Conversion Patterns: Func operations
211	//===----------------------------------------------------------------------===//
212	
213	struct FuncOpLowering : public OpConversionPattern<toy::FuncOp> {
214	  using OpConversionPattern<toy::FuncOp>::OpConversionPattern;
215	
216	  LogicalResult
217	  matchAndRewrite(toy::FuncOp op, OpAdaptor adaptor,
218	                  ConversionPatternRewriter &rewriter) const final {
219	    // We only lower the main function as we expect that all other functions
220	    // have been inlined.
221	    if (op.getName() != "main")
222	      return failure();
223	
224	    // Verify that the given main has no inputs and results.
225	    if (op.getNumArguments() || op.getFunctionType().getNumResults()) {
226	      return rewriter.notifyMatchFailure(op, [](Diagnostic &diag) {
227	        diag << "expected 'main' to have 0 inputs and 0 results";
228	      });
229	    }
230	
231	    // Create a new non-toy function, with the same region.
232	    auto func = mlir::func::FuncOp::create(rewriter, op.getLoc(), op.getName(),
233	                                           op.getFunctionType());
234	    rewriter.inlineRegionBefore(op.getRegion(), func.getBody(), func.end());
235	    rewriter.eraseOp(op);
236	    return success();
237	  }
238	};
239	
240	//===----------------------------------------------------------------------===//
241	// ToyToAffine Conversion Patterns: Print operations
242	//===----------------------------------------------------------------------===//
243	
244	struct PrintOpLowering : public OpConversionPattern<toy::PrintOp> {
245	  using OpConversionPattern<toy::PrintOp>::OpConversionPattern;
246	
247	  LogicalResult
248	  matchAndRewrite(toy::PrintOp op, OpAdaptor adaptor,
249	                  ConversionPatternRewriter &rewriter) const final {
250	    // We don't lower "toy.print" in this pass, but we need to update its
251	    // operands.
252	    rewriter.modifyOpInPlace(op,
253	                             [&] { op->setOperands(adaptor.getOperands()); });
254	    return success();
255	  }
256	};
257	
258	//===----------------------------------------------------------------------===//
259	// ToyToAffine Conversion Patterns: Return operations
260	//===----------------------------------------------------------------------===//
261	
262	struct ReturnOpLowering : public OpConversionPattern<toy::ReturnOp> {
263	  using OpConversionPattern<toy::ReturnOp>::OpConversionPattern;
264	
265	  LogicalResult
266	  matchAndRewrite(toy::ReturnOp op, OpAdaptor adaptor,
267	                  ConversionPatternRewriter &rewriter) const final {
268	    // During this lowering, we expect that all function calls have been
269	    // inlined.
270	    if (op.hasOperand())
271	      return failure();
272	
273	    // We lower "toy.return" directly to "func.return".
274	    rewriter.replaceOpWithNewOp<func::ReturnOp>(op);
275	    return success();
276	  }
277	};
278	
279	//===----------------------------------------------------------------------===//
280	// ToyToAffine Conversion Patterns: Transpose operations
281	//===----------------------------------------------------------------------===//
282	
283	struct TransposeOpLowering : public OpConversionPattern<toy::TransposeOp> {
284	  using OpConversionPattern<toy::TransposeOp>::OpConversionPattern;
285	
286	  LogicalResult
287	  matchAndRewrite(toy::TransposeOp op, OpAdaptor adaptor,
288	                  ConversionPatternRewriter &rewriter) const final {
289	    auto loc = op->getLoc();
290	    lowerOpToLoops(op, rewriter, [&](OpBuilder &builder, ValueRange loopIvs) {
291	      Value input = adaptor.getInput();
292	
293	      // Transpose the elements by generating a load from the
294	      // reverse indices.
295	      SmallVector<Value, 2> reverseIvs(llvm::reverse(loopIvs));
296	      return affine::AffineLoadOp::create(builder, loc, input, reverseIvs);
297	    });
298	    return success();
299	  }
300	};
