27	namespace toy {
28	
29	/// A variable type with shape information.
30	struct VarType {
31	  std::vector<int64_t> shape;
32	};
33	
34	/// Base class for all expression nodes.
35	class ExprAST {
36	public:
37	  enum ExprASTKind {
38	    Expr_VarDecl,
39	    Expr_Return,
40	    Expr_Num,
41	    Expr_Literal,
42	    Expr_Var,
43	    Expr_BinOp,
44	    Expr_Call,
45	    Expr_Print,
46	  };
47	
48	  ExprAST(ExprASTKind kind, Location location)
49	      : kind(kind), location(std::move(location)) {}
50	  virtual ~ExprAST() = default;
51	
52	  ExprASTKind getKind() const { return kind; }
53	
54	  const Location &loc() { return location; }
55	
56	private:
57	  const ExprASTKind kind;
58	  Location location;
59	};
60	
61	/// A block-list of expressions.
62	using ExprASTList = std::vector<std::unique_ptr<ExprAST>>;
63	
64	/// Expression class for numeric literals like "1.0".
65	class NumberExprAST : public ExprAST {
66	  double val;
67	
68	public:
69	  NumberExprAST(Location loc, double val)
70	      : ExprAST(Expr_Num, std::move(loc)), val(val) {}
71	
72	  double getValue() { return val; }
73	
74	  /// LLVM style RTTI
75	  static bool classof(const ExprAST *c) { return c->getKind() == Expr_Num; }
76	};
77	
78	/// Expression class for a literal value.
79	class LiteralExprAST : public ExprAST {
80	  std::vector<std::unique_ptr<ExprAST>> values;
81	  std::vector<int64_t> dims;
82	
83	public:
84	  LiteralExprAST(Location loc, std::vector<std::unique_ptr<ExprAST>> values,
85	                 std::vector<int64_t> dims)
86	      : ExprAST(Expr_Literal, std::move(loc)), values(std::move(values)),
87	        dims(std::move(dims)) {}
88	
89	  llvm::ArrayRef<std::unique_ptr<ExprAST>> getValues() { return values; }
90	  llvm::ArrayRef<int64_t> getDims() { return dims; }
91	
92	  /// LLVM style RTTI
93	  static bool classof(const ExprAST *c) { return c->getKind() == Expr_Literal; }
94	};
95	
96	/// Expression class for referencing a variable, like "a".
97	class VariableExprAST : public ExprAST {
98	  std::string name;
99	
100	public:
101	  VariableExprAST(Location loc, llvm::StringRef name)
102	      : ExprAST(Expr_Var, std::move(loc)), name(name) {}
103	
104	  llvm::StringRef getName() { return name; }
105	
106	  /// LLVM style RTTI
107	  static bool classof(const ExprAST *c) { return c->getKind() == Expr_Var; }
108	};
109	
110	/// Expression class for defining a variable.
111	class VarDeclExprAST : public ExprAST {
112	  std::string name;
113	  VarType type;
114	  std::unique_ptr<ExprAST> initVal;
115	
116	public:
117	  VarDeclExprAST(Location loc, llvm::StringRef name, VarType type,
118	                 std::unique_ptr<ExprAST> initVal)
119	      : ExprAST(Expr_VarDecl, std::move(loc)), name(name),
120	        type(std::move(type)), initVal(std::move(initVal)) {}
121	
122	  llvm::StringRef getName() { return name; }
123	  ExprAST *getInitVal() { return initVal.get(); }
124	  const VarType &getType() { return type; }
