127	  static bool classof(const ExprAST *c) { return c->getKind() == Expr_VarDecl; }
128	};
129	
130	/// Expression class for a return operator.
131	class ReturnExprAST : public ExprAST {
132	  std::optional<std::unique_ptr<ExprAST>> expr;
133	
134	public:
135	  ReturnExprAST(Location loc, std::optional<std::unique_ptr<ExprAST>> expr)
136	      : ExprAST(Expr_Return, std::move(loc)), expr(std::move(expr)) {}
137	
138	  std::optional<ExprAST *> getExpr() {
139	    if (expr.has_value())
140	      return expr->get();
141	    return std::nullopt;
142	  }
