145	  static bool classof(const ExprAST *c) { return c->getKind() == Expr_Return; }
146	};
147	
148	/// Expression class for a binary operator.
149	class BinaryExprAST : public ExprAST {
150	  char op;
151	  std::unique_ptr<ExprAST> lhs, rhs;
152	
153	public:
154	  char getOp() { return op; }
155	  ExprAST *getLHS() { return lhs.get(); }
156	  ExprAST *getRHS() { return rhs.get(); }
157	
158	  BinaryExprAST(Location loc, char op, std::unique_ptr<ExprAST> lhs,
159	                std::unique_ptr<ExprAST> rhs)
160	      : ExprAST(Expr_BinOp, std::move(loc)), op(op), lhs(std::move(lhs)),
161	        rhs(std::move(rhs)) {}
162	
163	  /// LLVM style RTTI
164	  static bool classof(const ExprAST *c) { return c->getKind() == Expr_BinOp; }
165	};
166	
167	/// Expression class for function calls.
168	class CallExprAST : public ExprAST {
169	  std::string callee;
170	  std::vector<std::unique_ptr<ExprAST>> args;
171	
